INSERT INTO "progression_rules" VALUES('pr_1','run_base','duration','2 successful sessions at RPE <=4 and no symptoms','increase duration 5-10 min',15.0,'Conservative run build');
INSERT INTO "progression_rules" VALUES('pr_2','run_quality','repeat_count','all reps within 3% pace spread at RPE <=7','add 1 repeat OR reduce recovery',10.0,'Do not raise intensity and volume together');
INSERT INTO "progression_rules" VALUES('pr_3','ski_base','duration','2 successful sessions at RPE <=4','increase 5 min',15.0,'Low-impact engine');
INSERT INTO "progression_rules" VALUES('pr_4','strength_legs','load','all work sets completed at RPE <=7','increase 2.5-5%',5.0,'Autoregulated');
INSERT INTO "progression_rules" VALUES('pr_5','strength_push','load','all work sets completed at RPE <=7','increase 2.5-5%',5.0,'Autoregulated');
INSERT INTO "progression_rules" VALUES('pr_6','strength_pull','load','all work sets completed at RPE <=7','increase 2.5-5%',5.0,'Autoregulated');
INSERT INTO "progression_rules" VALUES('pr_7','hybrid','density','repeatable splits at RPE <=7','add 1 round OR 5-10% station volume',10.0,'One variable at a time');
INSERT INTO "progression_rules" VALUES('pr_8','strength_total','load','all work sets completed at RPE <=7','increase 2.5-5%',5.0,'Autoregulated. Same rule as the regional strength families; a total-body session is not a different kind of lifting.');
INSERT INTO "progression_rules" VALUES('pr_9','strength_maintenance_lower','load','never - reduced dose by design','hold',0.0,'A reduced dose by design. Completing it earns no heavier prescription, and is not evidence of decline either - the load was lower because the session asked for less, not because the athlete could do less.');
INSERT INTO "progression_rules" VALUES('pr_10','strength_maintenance_upper','load','never - reduced dose by design','hold',0.0,'A reduced dose by design. Completing it earns no heavier prescription, and is not evidence of decline either - the load was lower because the session asked for less, not because the athlete could do less.');
INSERT INTO "station_programming_rules" VALUES('spr_any_aerobic_local_durability','*','aerobic_local_durability','Preserve primary station stimulus; reduce rounds/accessory volume to ~60-70%; keep movement quality.','10-20 minute minimum effective dose; ~25-40% volume; never raise intensity to compensate.','Progress one variable at a time: volume OR load OR density OR pace. Typical cap 5-10% per exposure unless benchmark/retest.','["time","RPE","load","HR_if_relevant","breaks_or_no_reps","pace_or_split_if_relevant","transition_time_if_hybrid"]',NULL,'v1');
INSERT INTO "station_programming_rules" VALUES('spr_any_complementary_hybrid','*','complementary_hybrid','Preserve primary station stimulus; reduce rounds/accessory volume to ~60-70%; keep movement quality.','10-20 minute minimum effective dose; ~25-40% volume; never raise intensity to compensate.','Progress one variable at a time: volume OR load OR density OR pace. Typical cap 5-10% per exposure unless benchmark/retest.','["time","RPE","load","HR_if_relevant","breaks_or_no_reps","pace_or_split_if_relevant","transition_time_if_hybrid"]',NULL,'v1');
INSERT INTO "station_programming_rules" VALUES('spr_any_compromised_station_work','*','compromised_station_work','Preserve primary station stimulus; reduce rounds/accessory volume to ~60-70%; keep movement quality.','10-20 minute minimum effective dose; ~25-40% volume; never raise intensity to compensate.','Progress one variable at a time: volume OR load OR density OR pace. Typical cap 5-10% per exposure unless benchmark/retest.','["time","RPE","load","HR_if_relevant","breaks_or_no_reps","pace_or_split_if_relevant","transition_time_if_hybrid"]',NULL,'v1');
