INSERT INTO "station_programming_rules" VALUES('spr_run_active_recovery','Run','active_recovery','Preserve the session''s primary running stimulus. Reduce repetitions or total duration to ~60-70%; do not make the remaining work harder.','Preserve a 10-20 minute minimum useful dose when appropriate. Do not compensate for lost volume by increasing intensity.','Progress one variable per exposure: continuous duration, total quality minutes, repetitions, pace, or recovery. Typical volume increase 5-10% when prior exposure is symptom-free and within target RPE.','["duration","distance","pace","avg_hr","max_hr","RPE","continuous_run_minutes","walk_breaks","treadmill_speed","incline","post_station_pace_if_hybrid"]',NULL,'v1');
